import{_ as t,o,c as a,ag as r}from"./chunks/framework.B_zcDAFh.js";const u=JSON.parse('{"title":"Boing Effector","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-effector.md","filePath":"guide/boing-effector.md"}'),i={name:"guide/boing-effector.md"};function n(s,e,l,c,f,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="boing-effector" tabindex="-1">Boing Effector <a class="header-anchor" href="#boing-effector" aria-label="Permalink to &quot;Boing Effector&quot;">​</a></h1><p>Add <strong>Boing Effector</strong> to a GameObject that should <em>push</em> other things. The effector itself doesn&#39;t deform — it applies influence to nearby <a href="./boing-reactor.html">Boing Reactors</a>, <a href="./boing-reactor-field.html">Boing Reactor Fields</a>, and <a href="./boing-bones.html">Boing Bones</a>.</p><p>Typical uses: a player or projectile nudging decorative objects, a wind source displacing grass or hair, an explosion radiating outward through a field.</p><h2 id="inspector-at-a-glance" tabindex="-1">Inspector at a Glance <a class="header-anchor" href="#inspector-at-a-glance" aria-label="Permalink to &quot;Inspector at a Glance&quot;">​</a></h2><ul><li><strong>Radius / Full Effect Radius Ratio</strong> — full influence inside <code>Radius * FullEffectRadiusRatio</code>, then falls off linearly to zero at <code>Radius</code>.</li><li><strong>Max Impulse Speed</strong> — effector speed at which impulse effects (linear/angular) reach full strength. Slower motion produces a proportionally smaller kick.</li><li><strong>Continuous Motion</strong> — when enabled, the effector affects everything along its swept path between frames, not just the discrete frame positions. Useful for fast-moving projectiles.</li><li><strong>Move Distance</strong> — how far reactors are displaced away from the effector at full influence.</li><li><strong>Linear Impulse</strong> — minimum outward speed (units/sec) reactors are kicked to at full influence.</li><li><strong>Rotation Angle / Angular Impulse</strong> — how much reactors&#39; up vectors are rotated and pushed away from the effector.</li></ul><p>See the <a href="/boing-kit/api/boing-effector.html">API reference</a>.</p>',6)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
